심장이식을 고려하지 않은 경우

proc phreg data=heart;
model futime*fustat(0)=transplant age surgery;
run;


심장이식을 고려한 경우

proc phreg data=heart;
model futime*fustat(0)=plant age surgery;
if wait_time&gt;futime or wait_time=. then plant=0; else plant=1;
run;

4.9 SAS 예제

CIF and Gray test

proc lifetest data=byar plots=cif(test);
time dtime*status2(0) / eventcode=1;
strata rx;
run;


No competing risk model

proc phreg data=byar zph;
*class rx;
model dtime*status2(0) = rx age wt pf hx hb sz sg / risklimits;
run;

Cause-specific model

proc phreg data=byar;
*class rx;
model dtime*status2(0,2,3) = rx age wt pf hx hb sz sg / risklimits;
run;


Subdistribution model

proc phreg data=byar;
model dtime*status2(0) = rx age wt pf hx hb sz sg / eventcode=1 risklimits;
run;

5.8 SAS 예제

Exponential AFT

proc lifereg data=anderson;
model time*status(0) = rx logWBC sex / dist=exponential;
run;


Weibull AFT

proc lifereg data=anderson;
model time*status(0) = rx logWBC sex / dist=weibull;
run;


Lognormal AFT

proc lifereg data=anderson;
model time*status(0) = rx logWBC sex / dist=lnormal;
run;
